+    private static Sequence readSequence(byte[] buf, int off) {
+        final int start = off;
+        final int token = buf[off++] & 0xFF;
+        int literalLen = token >>> 4;
+        if (literalLen >= 0x0F) {
+            int len;
+            while ((len = buf[off++] & 0xFF) == 0xFF) {
+                literalLen += 0xFF;
+            }
+            literalLen += len;
+        }
+        off += literalLen;
+        if (off == buf.length) {
+            return new Sequence(literalLen, -1, -1, off - start);
