+    public void stopLoadingStoredFields() {
+        current.getTimer(FetchPhaseTiming.LOAD_STORED_FIELDS).stop();
+    }
+
+    @Override
+    public void startNextReader() {
+        current.getTimer(FetchPhaseTiming.NEXT_READER).start();
+    }
+
+    @Override
+    public void stopNextReader() {
